// LinkedIn-Verbindung erinnern: läuft eine Verbindung in den nächsten 7 Tagen ab (oder ist schon abgelaufen)
// und wurde für genau diesen Ablaufwert noch nicht erinnert, kommt EINE Chat-Nachricht.
// Merker: ally_nutzer_einstellungen linkedin_erinnert bzw. ally_einstellungen linkedin_seite_erinnert = Ablaufwert.
// Chat-Layout (Vorgabe Stefan): Titel fett mit Doppelpunkt, Inhalt direkt darunter, keine Emojis.
// Testläufe (alles außer production) senden nichts und speichern nichts.
const test = $execution.mode !== 'production';
const roh = $input.first().json.eintraege;
const eintraege = Array.isArray(roh) ? roh : [];
const jetzt = Date.now();
const GRENZE = 7 * 24 * 60 * 60 * 1000;
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '').trim();
const esc = v => ohneEmoji(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const datum = d => {
  const t = {};
  for (const p of new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric' }).formatToParts(d)) t[p.type] = p.value;
  return t.day + '.' + t.month + '.' + t.year;
};
const WEG = 'Einstellungen › Marketing › Veröffentlichen › LinkedIn';
const out = [];
for (const e of eintraege) {
  const ablauf = String((e && e.ablauf) || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}/.test(ablauf)) continue;
  const d = new Date(ablauf);
  if (isNaN(d.getTime())) continue;
  if (d.getTime() - jetzt > GRENZE) continue;
  if (String(e.erinnert || '') === ablauf) continue;
  const userId = String(e.user_id || '').trim();
  if (!userId) continue;
  const abgelaufen = d.getTime() <= jetzt;
  const name = ohneEmoji(e.name);
  const klammer = name ? ' (' + name + ')' : '';
  const art = e.art === 'seite' ? 'seite' : 'person';
  const was = art === 'seite' ? 'Die LinkedIn-Unternehmensseite' : 'Dein persönliches LinkedIn-Profil';
  const titel = abgelaufen ? 'LinkedIn-Verbindung abgelaufen:' : 'LinkedIn-Verbindung läuft ab:';
  const satz = was + klammer + (abgelaufen ? ' war bis ' : ' ist noch bis ') + datum(d) + ' verbunden. Bitte unter ' + WEG + ' neu verbinden.';
  out.push({ json: {
    art, user_id: userId, room_id: String(e.room_id || ''), ablauf,
    text: titel + '\n' + satz,
    html: '<strong>' + esc(titel) + '</strong><br>' + esc(satz),
    test
  } });
}
return out;
